#[global_allocator]
static ALLOCATOR: alloc::VkAlloc = alloc::VkAlloc;

const SCHEMA: &str = "vk-scale-v1";

fn emit(mut line: Value) {
    line["schema"] = json!(SCHEMA);
    let mut out = std::io::stdout().lock();
    let _ = writeln!(out, "{line}");
    let _ = out.flush();
}

/// A phase's elapsed time and heap peaks, then a fresh stage.
struct Phase(Instant);

impl Phase {
    fn start() -> Self {
        alloc::stage_reset();
        Phase(Instant::now())
    }
    fn fields(&self) -> Value {
        json!({
            "elapsed_ns": self.0.elapsed().as_nanos() as u64,
            "heap_peak": alloc::stage_peak(),
            "heap_peak_move": alloc::stage_peak_move(),
            "heap_current": alloc::current(),
        })
    }
}

fn merge(mut a: Value, b: Value) -> Value {
    if let (Some(a), Value::Object(b)) = (a.as_object_mut(), b) {
        a.extend(b);
    }
    a
}

fn fail(code: i32, kind: &str, why: String) -> ! {
    emit(json!({ "kind": kind, "reason": why }));
    std::process::exit(code);
        fail(2, "usage", "--heap-cap-bytes is required".into());
    };
    alloc::set_cap(cap);
    if a.noop {
        emit(json!({ "kind": "start", "noop": true, "heap_cap_bytes": cap }));
        emit(json!({
            "kind": "summary", "repeats_heap_peak": alloc::peak(),
            "repeats_heap_peak_move": alloc::peak_move(),
        }));
        return;
    }
    let Some(id) = a.case.clone() else {
        fail(2, "usage", "--case is required".into());
    };

    // ------------------------------------------------------------ load
    let phase = Phase::start();
    let Some(case) = load_family("RF-LARGE").into_iter().find(|c| c.id == id) else {
        fail(4, "error", format!("unknown case {id}"));
    };
    let (model, model_sha256): (Model, Option<String>) = match (&case.model, &a.model_file) {
        (Some(m), None) => (m.clone(), None),
        (None, Some(path)) => {
            let (m, sha) = load_large_model(std::path::Path::new(path));
            (m, Some(sha))
        }
        _ => fail(
            2,
            "usage",
            format!("{id}: --model-file is needed exactly when the case has no committed model"),
        ),
    };
    if let (Some(got), Some(want)) = (&model_sha256, &case.model_sha256) {
        if got != want {
            fail(
                4,
                "error",
                format!("{id}: model file sha256 {got}, committed {want}"),
            );
        }
    }
    emit(merge(
        json!({
            "kind": "start", "case": id, "members": model.members.len(),
            "heap_cap_bytes": cap, "model_sha256": model_sha256,
            "committed_model_sha256": case.model_sha256,
            "case_limit": u64::MAX, "invocation_limit": u64::MAX,
        }),
        phase.fields(),
    ));

    // ------------------------------------------------------------ counts
    let phase = Phase::start();
    let source = match PrimitiveSource::new(model.source_parts()) {
        Ok(s) => s,
        Err(e) => fail(4, "error", format!("{id}: source refused: {e:?}")),
    };
    let k4src = sha256::sha256_hex(&source.encoding());
    if k4src != case.k4src_sha256 {
        fail(
            4,
            "error",
            format!(
                "{id}: K4SRC sha256 {k4src}, the generator's {}",
                case.k4src_sha256
            ),
        );
    }
    let counts = scale::counts(&model, &source);
    drop(source);
    let sizes = scale::Sizes::of_this_build();
    let est = scale::estimate(&counts, &sizes);
    emit(merge(
        json!({
            "kind": "counts", "case": id, "k4src_sha256": k4src,
            "nodes": counts.nodes, "members": counts.members, "springs": counts.springs,
            "stations": counts.stations, "constraints": counts.constraints,
            "loads": counts.loads, "dofs": counts.dofs, "free_dofs": counts.free_dofs,
            "bodies": counts.bodies, "pattern_entries": counts.pattern_entries,
            "profile_entries": counts.profile_entries, "half_bandwidth": counts.half_bandwidth,
            "blocks": counts.blocks, "rows": counts.rows,
            "source_encoding_len": counts.source_encoding_len,
            "estimate_max_bytes": est.max as u64, "estimate_sel128_bytes": est.sel128 as u64,
            "estimate_fixed_bytes": est.fixed as u64, "estimate_model_bytes": est.model as u64,
            "estimate_decide_bytes": est.decide as u64,
        }),
        phase.fields(),
    ));
    if a.counts_only {
        emit(json!({
            "kind": "summary", "case": id, "counts_only": true,
            "repeats_heap_peak": alloc::peak(), "repeats_heap_peak_move": alloc::peak_move(),
        }));
        return;
    }
    if est.max > (cap / 2) as u128 {
        emit(json!({
            "kind": "refusal", "case": id, "reason": "estimate_exceeds_half_cap",
            "estimate_max_bytes": est.max as u64, "half_cap_bytes": cap / 2,
        }));
        std::process::exit(3);
    }

    // ------------------------------------------------------------ W1
    let phase = Phase::start();
    let mut run = lane::run_case_with(&case, &model);
    let w1 = phase.fields();
    let record = run.record.clone();
    let storage = &record["attempts"][0]["storage"];
    let counts_match_storage = storage["pattern_entries"].as_u64()
        == Some(counts.pattern_entries as u64)
        && storage["profile_entries"].as_u64() == Some(counts.profile_entries as u64);
    emit(merge(
        json!({
            "kind": "w1", "case": id, "outcome": record["outcome"],
            "selected_precision": record["selected_precision"],
            "verification_precision": record["verification_precision"],
            "attempts": record["attempts"].as_array().map(Vec::len),
            "corrections": record["corrections"],
            "invocation_charged": record["invocation_charged"],
            "published_rows": record["published_rows"],
            "counts_match_storage": counts_match_storage,
        }),
        w1,
    ));

    // ------------------------------------------------------------ report
    let phase = Phase::start();
    let not_covered_full = full_maxima(&case).map(|m| {
        let scales = floor::scales_from(m, &model);
        floor::not_covered(&case, &model, &scales)
    });
    let t = &run.tally;
    emit(merge(
        json!({
            "kind": "report", "case": id, "rows": t.rows, "pass": t.pass,
            "pass_absolute_range": t.pass_absolute_range, "not_covered": t.not_covered,
            "structural_zero": t.structural_zero, "expected_unresolved": t.expected_unresolved,
            "fail": t.fail, "accounted": t.accounted(),
            "failures": run.failures.len(),
            "failures_head": run.failures.iter().take(50).collect::<Vec<_>>(),
            "not_covered_rows": run.not_covered,
            "not_covered_committed": case.not_covered,
            "not_covered_equal": run.not_covered == case.not_covered,
            "not_covered_rows_s_full": not_covered_full,
            "class_mismatches": run.class_mismatches,
            "controls_discriminated": run.controls.discriminated,
            "controls_non_discriminating": run.controls.non_discriminating,
            "controls_undiscriminated": run.controls.undiscriminated,
            "controls_unexpectedly_failing": run.controls.unexpectedly_failing,
        }),
        phase.fields(),
    ));
    emit(json!({ "kind": "record", "case": id, "record": record }));
    run.published.clear();
    drop(run);

    // ------------------------------------------------------------ RCM
    let phase = Phase::start();
    let adjacency = rcm::free_adjacency(&model);
    let (k4, sd) = rcm::both_orders(&adjacency);
    let equal = k4 == sd;
    drop((adjacency, k4, sd));
    emit(merge(
        json!({ "kind": "rcm", "case": id, "equal": equal }),
        phase.fields(),
    ));

    // ------------------------------------------------------------ binary64
    let phase = Phase::start();
    let b64 = parity::parity(&model, false);
    emit(merge(
        match b64 {
            Ok(p) => json!({ "kind": "binary64", "case": id, "sparse": p.sparse }),
            Err(e) => json!({ "kind": "binary64", "case": id, "error": e }),
        },
        phase.fields(),
    ));

    emit(json!({
        "kind": "summary", "case": id,
        "repeats_heap_peak": alloc::peak(), "repeats_heap_peak_move": alloc::peak_move(),
    }));
}

//! The per-case records for ROOT's W1 limits (brief Scope 11; plan §12):
//! schema `vk-case-record-v1`, one object per case, committed per family in
//! `observations/kernel_lane/<family>.json` and compared by CI.
//!
//! Only deterministic content: the outcome, the selected and verification
//! precisions, each attempt's precision, role, outcome, corrections, gate,
//! work by stage (all 19 `StageWork` fields) and in total (K4's own limb
//! work and its exact-sum work), storage, and the report counts. No time, and
//! no binary64 value computed through FK's geometry (whose `hypot` is the
//! platform's): a witness is recorded by body only.
use crate::cases::Case;
use crate::compare::Tally;
use crate::lane::refusal_text;
use open_pipe_stress_frame_kernel::structural::retained_api::{
    AttemptRecord, CaseOutcome, InvocationMeter, StageWork,
};
use serde_json::{json, Map, Value};

pub const SCHEMA: &str = "vk-case-record-v1";

fn stages(s: &StageWork) -> Value {
    json!({
        "formation": s.formation, "assembly": s.assembly,
        "residual_formation": s.residual_formation, "factor": s.factor,
        "condition": s.condition, "rhs": s.rhs, "solve": s.solve,
        "refinement": s.refinement, "recovery": s.recovery, "stop_rule": s.stop_rule,
        "bounded_gate": s.bounded_gate, "scale": s.scale, "estimate": s.estimate,
        "charge": s.charge, "bound": s.bound, "shift": s.shift,
        "bounded_formation": s.bounded_formation, "wide_formation": s.wide_formation,
        "uc": s.uc,
    })
}

fn attempt(a: &AttemptRecord) -> Value {
    json!({
        "precision": a.precision,
        "role": format!("{:?}", a.role),
        "outcome": format!("{:?}", a.outcome),
        "residual_basis": a.residual_basis,
        "corrections": a.corrections,
        "gate": a.gate.as_ref().map(|g| format!("{g:?}")),
        "own_work": a.work.limb_multiply_equivalents(),
        "exact_sum_work": a.k4_work.limb_multiply_equivalents(),
        "stages": stages(&a.stages),
        "shared_work": a.shared_work,
        "shared_stages": stages(&a.shared_stages),
        "shared_built_here": a.shared_built_here,
        "stop_rule_work": a.stop_rule_work,
        "verification_work": a.verification_work,
        "verification_shared_work": a.verification_shared_work,
        "verification_shared_built_here": a.verification_shared_built_here,
        "storage": {
            "pattern_entries": a.storage.pattern_entries,
            "profile_entries": a.storage.profile_entries,
            "limbs_per_entry": a.storage.limbs_per_entry,
        },
        "verification": a.verification.as_ref().map(|v| json!({
            "data_blocks": v.data_blocks,
            "shift_factorizations": v.shift_factorizations,
            "uc_missing": v.uc_missing,
            "g_max": v.g_max,
            "g_violation": v.g_violation,
        })),
    })
}

fn report(t: &Tally) -> Value {
    json!({
        "rows": t.rows, "pass": t.pass, "pass_absolute_range": t.pass_absolute_range,
        "not_covered": t.not_covered, "structural_zero": t.structural_zero,
        "expected_unresolved": t.expected_unresolved, "fail": t.fail,
    })
}

/// The outcome as text, without platform-dependent values.
pub fn outcome_text(o: &CaseOutcome) -> String {
    match o {
        CaseOutcome::Selected(s) => format!("Selected at {}", s.selected_precision()),
        CaseOutcome::Refused { refusal, geometry } => {
            format!("Refused {} {geometry:?}", refusal_text(refusal))
        }
        CaseOutcome::Unresolved {
            reason, geometry, ..
        } => format!("Unresolved {reason:?} {geometry:?}"),
    }
}

pub fn case_record(case: &Case, o: &CaseOutcome, t: &Tally, meter: &InvocationMeter) -> Value {
    let mut r = Map::new();
    r.insert("schema".into(), json!(SCHEMA));
    r.insert("id".into(), json!(case.id));
    r.insert("family".into(), json!(case.family));
    r.insert("k4src_sha256".into(), json!(case.k4src_sha256));
    r.insert("outcome".into(), json!(outcome_text(o)));
    r.insert("case_limit".into(), json!(u64::MAX));
    r.insert("invocation_charged".into(), json!(meter.charged()));
    let attempts: Vec<Value> = match o {
        CaseOutcome::Selected(s) => {
            let e = s.evidence();
            r.insert("selected_precision".into(), json!(e.selected_precision));
            r.insert(
                "verification_precision".into(),
                json!(e.verification_precision),
            );
            r.insert("corrections".into(), json!(e.corrections));
            r.insert("geometry".into(), json!(format!("{:?}", e.geometry)));
            r.insert(
                "absolute_verified_rows".into(),
                json!(e.absolute_verified.len()),
            );
            r.insert("unpublishable_rows".into(), json!(e.unpublishable.len()));
            r.insert("published_rows".into(), json!(s.publish().rows.len()));
            e.attempts.iter().map(attempt).collect()
        }
        CaseOutcome::Unresolved { attempts, .. } => attempts.iter().map(attempt).collect(),
        CaseOutcome::Refused { .. } => Vec::new(),
    };
    r.insert("attempts".into(), Value::Array(attempts));
    r.insert("report".into(), report(t));
    Value::Object(r)
}

pub fn source_refused_record(case: &Case, error: &str, t: &Tally) -> Value {
    json!({
        "schema": SCHEMA, "id": case.id, "family": case.family,
        "k4src_sha256": case.k4src_sha256,
        "outcome": format!("SourceRefused {error}"), "attempts": [], "report": report(t),
    })
}

/// A family's records, as committed: a JSON array, keys sorted (serde_json's
/// default map), pretty-printed, a final newline.
pub fn family_file(records: &[Value]) -> String {
    let mut s = serde_json::to_string_pretty(&Value::Array(records.to_vec())).unwrap();
    s.push('\n');
    s
}

